--all-link-color:$(main.link.color);
--black-text:#000000;
--main-text-color:$(main.text.color);
--mobile-menu-bg:$(mobile.menu.bg.color);
--top-menu-text:$(top.bar.menufont);
--white-bg:#ffffff;
