document.addEventListener("DOMContentLoaded", function() {
  var imgs = document.querySelectorAll(".item-post .post-body img, .post-body img");
  Array.prototype.forEach.call(imgs, function(img) {
    var src = img.getAttribute("src") || "";
    if (src.indexOf("s320") !== -1) {
      img.src = src.replace(/\/s320(-rw)?\//g, "/s1600/").replace(/=s320(-rw)?/g, "=s1600");
    }
  });
});
